package com.devteciot.dev_erp.Controller; import com.devteciot.dev_erp.DTO.DTOTipoSaida.*; import com.devteciot.dev_erp.Service.TipoSaidaService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tipos-saidas") @RequiredArgsConstructor public class TipoSaidaController {private final TipoSaidaService s; @GetMapping public List<TipoSaidaGetDTO> listar(){return s.listar();}@GetMapping("/{id}") public TipoSaidaGetDTO buscar(@PathVariable Long id){return s.buscar(id);}@PostMapping public ResponseEntity<TipoSaidaGetDTO> criar(@Valid @RequestBody TipoSaidaPostDTO d){return ResponseEntity.status(HttpStatus.CREATED).body(s.criar(d));}@PutMapping("/{id}") public TipoSaidaGetDTO atualizar(@PathVariable Long id,@Valid @RequestBody TipoSaidaPostDTO d){return s.atualizar(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Long id){s.excluir(id);return ResponseEntity.noContent().build();}}
